import{_ as n,o as s,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Drehbuch-Update: Szene 50 - Das ewige Schaufenster","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/szene-ewiges-schaufenster.md","filePath":"logbuch/szene-ewiges-schaufenster.md"}'),r={name:"logbuch/szene-ewiges-schaufenster.md"};function a(u,e,h,d,g,l){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="drehbuch-update-szene-50-das-ewige-schaufenster" tabindex="-1">Drehbuch-Update: Szene 50 - Das ewige Schaufenster <a class="header-anchor" href="#drehbuch-update-szene-50-das-ewige-schaufenster" aria-label="Permalink to &quot;Drehbuch-Update: Szene 50 - Das ewige Schaufenster&quot;">​</a></h1><p><strong>STIL:</strong> Surrealistisch. Der Raum hat keine Wände. Im Hintergrund schweben Jugendstil-Regale mit Pelzmänteln neben modernen Glasvitrinen voller Diamanten. Der Boden ist aus schwarzem Marmor, der das Licht wie Wasser reflektiert.</p><p><strong>BESETZUNG:</strong></p><ul><li><strong>Helmut Horten:</strong> August Diehl (in einem strengen, dunklen Anzug der 30er Jahre)</li><li><strong>Heidi Horten:</strong> Birgit Minichmayr (in einer Robe, die aus purem Gold zu bestehen scheint)</li></ul><hr><p><strong>INT. DER ZWISCHENRAUM - JENSEITS DER ZEIT</strong></p><p>Helmut (Diehl) steht an einem gläsernen Verkaufstresen und poliert mit einem weißen Tuch eine unsichtbare Oberfläche. Heidi (Minichmayr) tritt aus dem Nebel auf ihn zu. Sie trägt eine Kette aus Perlen, die so groß sind wie Taubeneier.</p><p><strong>HEIDI</strong> (lächelt amüsiert) Immer noch am Polieren, Helmut? Die Welt da draußen hat längst vergessen, wie man Glas richtig putzt. Heute wird alles nur noch... weggewischt. Digital.</p><p><strong>HELMUT</strong> (sieht nicht auf) Präzision, Heidi. Ein Schaufenster muss makellos sein. Wenn der Kunde sein eigenes Spiegelbild darin nicht bewundern kann, wird er nie verstehen, dass er ohne das Produkt dahinter unvollständig ist.</p><p>Er legt das Tuch weg und sieht sie an. Sein Blick ist durchdringend.</p><p><strong>HELMUT</strong> Ich habe dir ein Imperium hinterlassen, das auf Logik und Schweigen gebaut war. Was hast du daraus gemacht? Einen Zirkus aus Farben und Spendenlisten.</p><p><strong>HEIDI</strong> (nimmt einen tiefen Zug aus einer langen Zigarettenspitze) Einen <em>schönen</em> Zirkus, Helmut. Das Schweigen ist heute nichts mehr wert. Heute muss man so laut sein, dass die Leute vor lauter Lärm vergessen, die richtigen Fragen zu stellen. Deine Kaufhäuser waren Kathedralen der Ware. Ich habe daraus eine Religion der Gefälligkeit gemacht.</p><p>Sie gleitet mit der Hand über eine schwebende Vitrine.</p><p><strong>HEIDI</strong> Wusstest du, dass sie jetzt meine Festplatten schreddern? In deinem Namen. Na ja, eigentlich im Namen eines jungen Mannes mit sehr vielen Haaren und sehr wenig Geduld.</p><p><strong>HELMUT</strong> (zieht die Augenbrauen hoch) Festplatten?</p><p><strong>HEIDI</strong> Sowas wie deine Kontobücher, nur... anfälliger für die Wahrheit. Aber keine Sorge. Ich habe ihnen beigebracht, wie man das Gold so fein mahlt, dass es wie Staub aussieht. Pointillismus, Helmut. Du hast in Blöcken gedacht. Ich denke in Punkten.</p><p><strong>HELMUT</strong> (tritt einen Schritt auf sie zu) Und die Alsbergs? Die Geister in den Gängen?</p><p><strong>HEIDI</strong> (lacht rauchig) Die haben wir in den Keller geschickt. Zu den Eurofightern und den Ibiza-Tapes. Es ist sehr voll dort unten, Helmut. Aber hier oben... hier oben ist es wunderbar hell.</p><p>Sie reicht ihm ein Glas Champagner, das aus dem Nichts erscheint.</p><p><strong>HEIDI</strong> Trink auf uns. Auf das ewige Schaufenster. Solange die Leute glauben, dass sie uns brauchen, wird dieses Museum niemals schließen.</p><p>Helmut nimmt das Glas. Zum ersten Mal huscht ein Schatten eines Lächelns über sein Gesicht.</p><p><strong>HELMUT</strong> Auf die Marktbereinigung.</p><p><strong>HEIDI</strong> (stößt an) Auf die Ästhetik der Macht.</p><p><strong>FADE TO WHITE.</strong></p>',24)])])}const m=n(r,[["render",a]]);export{c as __pageData,m as default};
